#include "ggml.h"
#include "ggml-backend-impl.h"
#include "ggml-alloc.h"
#include "ggml-impl.h"
#include "ggml-expert-pipeline.h"
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <deque>
#include <functional>
#include <vector>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"FAIL %d %s\n",__LINE__,#x);exit(2);}}while(0)
struct Mock;
struct Evt{Mock*m;uint64_t seq;};
struct Mock{ggml_backend b={};ggml_backend_device d={};ggml_backend_buffer_type bt={};ggml_backend_reg reg={};bool gpu=false,async=true,events=true,deps=false;int live=0,allocs=0,free_count=0,fail_alloc=0,computes=0,fail_compute=0,syncs=0,copies=0,waits=0,records=0,event_syncs=0,event_live=0,evals=0,copy_cb=0,query=0,reserve=0,bind=0,begin=0,end=0,cancel=0;bool pipeline=false,callback_accept=false;uint64_t next=0,done=0;std::deque<std::pair<uint64_t,std::function<void()>>>queue;};
static Mock* mock(ggml_backend_t b){return (Mock*)b->context;}
static Mock* device(ggml_backend_dev_t d){return (Mock*)d->context;}
static void flush(Mock*m,uint64_t limit=UINT64_MAX){while(!m->queue.empty()&&m->queue.front().first<=limit){auto item=std::move(m->queue.front());m->queue.pop_front();item.second();m->done=item.first;}}
static void enqueue(Mock*m,std::function<void()>f){m->queue.push_back({++m->next,std::move(f)});}
static const char* bname(ggml_backend_t b){return mock(b)->gpu?"MOCK_GPU":"MOCK_CPU";}
static const char* tname(ggml_backend_buffer_type_t b){return ((Mock*)b->context)->gpu?"MOCK_GPU_BUFT":"MOCK_CPU_BUFT";}
static const char* dname(ggml_backend_dev_t d){return device(d)->gpu?"MOCK_GPU":"MOCK_CPU";}
static const char* rname(ggml_backend_reg_t){return "MOCK_REG";}
static size_t align(ggml_backend_buffer_type_t){return 64;}
static bool is_host(ggml_backend_buffer_type_t b){return !((Mock*)b->context)->gpu;}
static void release(ggml_backend_buffer_t b){auto*m=(Mock*)b->buft->context;CHECK(m->live>0);m->live--;m->free_count++;free(b->context);}
static void* base(ggml_backend_buffer_t b){return b->context;}
static void set(ggml_backend_buffer_t,ggml_tensor*t,const void*p,size_t off,size_t n){memcpy((char*)t->data+off,p,n);}
static void get(ggml_backend_buffer_t,const ggml_tensor*t,void*p,size_t off,size_t n){memcpy(p,(char*)t->data+off,n);}
static void clear(ggml_backend_buffer_t b,uint8_t value){memset(b->context,value,b->size);}
static ggml_backend_buffer_t alloc(ggml_backend_buffer_type_t bt,size_t n){auto*m=(Mock*)bt->context;m->allocs++;if(m->allocs==m->fail_alloc)return nullptr;void*p=nullptr;CHECK(!posix_memalign(&p,64,n));ggml_backend_buffer_i i={};i.free_buffer=release;i.get_base=base;i.set_tensor=set;i.get_tensor=get;i.clear=clear;m->live++;return ggml_backend_buffer_init(bt,i,p,n);}
static enum ggml_backend_dev_type dtype(ggml_backend_dev_t d){return device(d)->gpu?GGML_BACKEND_DEVICE_TYPE_GPU:GGML_BACKEND_DEVICE_TYPE_CPU;}
static ggml_backend_buffer_type_t buft(ggml_backend_dev_t d){return &device(d)->bt;}
static bool supports(ggml_backend_dev_t,const ggml_tensor*){return true;}
static bool supports_buft(ggml_backend_dev_t d,ggml_backend_buffer_type_t bt){return bt==&device(d)->bt;}
static bool offload(ggml_backend_dev_t,const ggml_tensor*){return true;}
static void sync(ggml_backend_t b){auto*m=mock(b);m->syncs++;flush(m);}
static ggml_backend_event_t evnew(ggml_backend_dev_t d){auto*m=device(d);if(!m->events)return nullptr;auto*e=new ggml_backend_event{d,new Evt{m,0}};m->event_live++;return e;}
static void evfree(ggml_backend_dev_t d,ggml_backend_event_t e){auto*m=device(d);CHECK(m->event_live>0);m->event_live--;delete (Evt*)e->context;delete e;}
static void evsync(ggml_backend_dev_t d,ggml_backend_event_t e){device(d)->event_syncs++;auto*c=(Evt*)e->context;flush(c->m,c->seq);}
static void evrecord(ggml_backend_t b,ggml_backend_event_t e){auto*m=mock(b);m->records++;auto*c=(Evt*)e->context;c->m=m;c->seq=m->next;}
static void evwait(ggml_backend_t b,ggml_backend_event_t e){auto*m=mock(b);m->waits++;auto c=*(Evt*)e->context;enqueue(m,[c]{flush(c.m,c.seq);});}
static bool cpy(ggml_backend_t src,ggml_backend_t dst,const ggml_tensor*a,ggml_tensor*b){auto*m=mock(dst);m->copies++;if(!m->async)return false;auto*sm=mock(src);auto seq=sm->next;enqueue(m,[sm,seq,a,b]{flush(sm,seq);memcpy(b->data,a->data,ggml_nbytes(a));});return true;}
static void numerical(ggml_tensor*t){if(t->op==GGML_OP_NONE||t->view_src)return;if(t->op==GGML_OP_MUL_MAT_ID){memset(t->data,0,ggml_nbytes(t));return;}CHECK(t->type==GGML_TYPE_F32);auto*out=(float*)t->data;auto*a=(float*)t->src[0]->data;size_t n=ggml_nelements(t);if(t->op==GGML_OP_ADD){auto*b=(float*)t->src[1]->data;for(size_t i=0;i<n;i++)out[i]=a[i]+b[i];}else if(t->op==GGML_OP_SQR){for(size_t i=0;i<n;i++)out[i]=a[i]*a[i];}else{fprintf(stderr,"unsupported fixture op %d\n",t->op);exit(2);}}
static ggml_status compute(ggml_backend_t b,ggml_cgraph*g){auto*m=mock(b);m->computes++;if(m->computes==m->fail_compute)return GGML_STATUS_ABORTED;std::vector<ggml_tensor*>nodes(g->nodes,g->nodes+g->n_nodes);enqueue(m,[nodes]{for(auto*t:nodes)numerical(t);});return GGML_STATUS_SUCCESS;}
static void optimize(ggml_backend_t b,ggml_cgraph*g,ggml_backend_graph_optimize_params*p){auto*m=mock(b);if(m->deps&&g->n_nodes>1){auto*last=g->nodes[g->n_nodes-1];for(int i=0;i<g->n_nodes-1;i++){p->add_alloc_dep(p->user_data,g->nodes[i],last);p->add_alloc_dep(p->user_data,g->nodes[i],last);}}}
static bool expert(ggml_backend_t b,decltype(GGML_EXPERT_QUERY) op,const ggml_tensor*,ggml_tensor*,size_t*size){auto*m=mock(b);switch(op){case GGML_EXPERT_QUERY:m->query++;*size=4096;return true;case GGML_EXPERT_RESERVE:m->reserve++;return true;case GGML_EXPERT_BIND:m->bind++;(*size)++;return true;case GGML_EXPERT_BEGIN:m->begin++;return true;case GGML_EXPERT_END:m->end++;return true;case GGML_EXPERT_CANCEL:m->cancel++;return true;default:return false;}}
static void*proc(ggml_backend_reg_t r,const char*name){auto*m=(Mock*)r->context;return m->pipeline&&!strcmp(name,"ggml_backend_expert_pipeline_v1")?(void*)expert:nullptr;}
static void initialize(Mock&m,bool gpu){m.gpu=gpu;m.b.context=&m;m.b.device=&m.d;m.b.iface.get_name=bname;m.b.iface.synchronize=sync;m.b.iface.graph_compute=compute;m.b.iface.cpy_tensor_async=cpy;m.b.iface.event_record=evrecord;m.b.iface.event_wait=evwait;m.b.iface.graph_optimize=optimize;m.d.context=&m;m.d.reg=&m.reg;m.d.iface.get_name=dname;m.d.iface.get_type=dtype;m.d.iface.get_buffer_type=buft;m.d.iface.supports_op=supports;m.d.iface.supports_buft=supports_buft;m.d.iface.offload_op=offload;m.d.iface.event_new=evnew;m.d.iface.event_free=evfree;m.d.iface.event_synchronize=evsync;m.bt.context=&m;m.bt.device=&m.d;m.bt.iface.get_name=tname;m.bt.iface.alloc_buffer=alloc;m.bt.iface.get_alignment=align;m.bt.iface.is_host=is_host;m.reg.api_version=GGML_BACKEND_API_VERSION;m.reg.context=&m;m.reg.iface.get_name=rname;m.reg.iface.get_proc_address=proc;}
static ggml_context*ctx(){auto*c=ggml_init({16*1024*1024,nullptr,true});CHECK(c);return c;}
static ggml_tensor*tensor(ggml_context*c,int n=16){return ggml_new_tensor_1d(c,GGML_TYPE_F32,n);}
static bool copycb(ggml_backend_t be,const ggml_tensor*src,ggml_tensor*dst,ggml_cgraph*,void*){auto*m=mock(be);m->copy_cb++;if(!m->callback_accept)return false;memcpy(dst->data,src->data,ggml_nbytes(src));return true;}
struct Eval{int asks=0,reads=0;bool stop=false;};
static bool eval(ggml_tensor*,bool ask,void*p){auto*e=(Eval*)p;if(ask){e->asks++;return true;}e->reads++;return !e->stop;}
static void check_clean(Mock&a,Mock&b){CHECK(!a.live&&!b.live&&!a.event_live&&!b.event_live);CHECK(a.queue.empty()&&b.queue.empty());}
static void flow(int parallel,bool events,bool async,int nodes,bool dependencies,int failure,bool stop){
 Mock gpu,cpu;initialize(gpu,true);initialize(cpu,false);gpu.events=cpu.events=events;gpu.async=cpu.async=async;gpu.deps=cpu.deps=dependencies;ggml_backend_t bes[]={&gpu.b,&cpu.b};auto s=ggml_backend_sched_new(bes,nullptr,2,4096,parallel,false);auto c=ctx();auto*x=tensor(c);ggml_set_input(x);ggml_tensor*z=x;for(int i=0;i<nodes;i++){z=ggml_add(c,z,x);ggml_backend_sched_set_tensor_backend(s,z,dependencies?&gpu.b:(i%2?&cpu.b:&gpu.b));}ggml_set_output(z);auto*g=ggml_new_graph_custom(c,4096,false);ggml_build_forward_expand(g,z);CHECK(ggml_backend_sched_alloc_graph(s,g));CHECK(ggml_backend_sched_get_n_splits(s)==(dependencies?1:nodes));float values[16];std::fill(values,values+16,1.f);ggml_backend_tensor_set(x,values,0,sizeof(values));Eval e;e.stop=stop;if(stop)ggml_backend_sched_set_eval_callback(s,eval,&e);if(failure){if(failure==2)cpu.fail_compute=cpu.computes+1;else gpu.fail_compute=gpu.computes+1;}auto status=ggml_backend_sched_graph_compute_async(s,g);CHECK(status==(failure?GGML_STATUS_ABORTED:GGML_STATUS_SUCCESS));ggml_backend_sched_synchronize(s);
 if(!failure&&!stop){float out[16];ggml_backend_tensor_get(z,out,0,sizeof(out));for(float v:out)CHECK(v==nodes+1.f);}if(stop)CHECK(e.reads>0&&e.reads<=ggml_backend_sched_get_n_splits(s));
 if(failure){gpu.fail_compute=cpu.fail_compute=0;CHECK(ggml_backend_sched_graph_compute(s,g)==GGML_STATUS_SUCCESS);float out[16];ggml_backend_tensor_get(z,out,0,sizeof(out));for(float v:out)CHECK(v==nodes+1.f);}
 if(parallel&&events)CHECK(gpu.records>0||failure);if(nodes>1&&!dependencies&&!stop&&!failure)CHECK(cpu.copies+gpu.copies>0);ggml_backend_sched_free(s);ggml_free(c);check_clean(gpu,cpu);
}
static void allocation_failure(){Mock gpu,cpu;initialize(gpu,true);initialize(cpu,false);ggml_backend_t bes[]={&gpu.b,&cpu.b};auto s=ggml_backend_sched_new(bes,nullptr,2,2048,false,false);auto c=ctx();auto*x=tensor(c);ggml_set_input(x);auto*z=ggml_add(c,x,x);ggml_backend_sched_set_tensor_backend(s,z,&gpu.b);ggml_set_output(z);auto*g=ggml_new_graph_custom(c,2048,false);ggml_build_forward_expand(g,z);gpu.fail_alloc=1;CHECK(!ggml_backend_sched_alloc_graph(s,g));CHECK(!gpu.live);ggml_backend_sched_reset(s);gpu.fail_alloc=0;CHECK(ggml_backend_sched_alloc_graph(s,g));float values[16];std::fill(values,values+16,2);ggml_backend_tensor_set(x,values,0,sizeof(values));CHECK(ggml_backend_sched_graph_compute(s,g)==GGML_STATUS_SUCCESS);ggml_backend_sched_free(s);ggml_free(c);check_clean(gpu,cpu);}
static void graph_inputs(){Mock gpu,cpu;initialize(gpu,true);initialize(cpu,false);ggml_backend_t bes[]={&gpu.b,&cpu.b};auto s=ggml_backend_sched_new(bes,nullptr,2,4096,true,false);auto c=ctx();auto*g=ggml_new_graph_custom(c,4096,false);for(int i=0;i<80;i++){auto*x=tensor(c);ggml_set_input(x);ggml_build_forward_expand(g,x);}CHECK(ggml_backend_sched_alloc_graph(s,g));ggml_backend_sched_synchronize(s);ggml_backend_sched_free(s);ggml_free(c);check_clean(gpu,cpu);}
static void expertflow(bool accepted){Mock gpu,cpu;initialize(gpu,true);initialize(cpu,false);gpu.pipeline=true;gpu.callback_accept=accepted;ggml_backend_t bes[]={&gpu.b,&cpu.b};auto s=ggml_backend_sched_new(bes,nullptr,2,2048,false,false);ggml_backend_sched_set_expert_pipeline(s,true);ggml_backend_sched_set_copy_callback(s,copycb,nullptr);auto weights=ctx();auto*w=tensor(weights,64);auto wb=ggml_backend_alloc_ctx_tensors_from_buft(weights,&cpu.bt);CHECK(wb);ggml_backend_buffer_set_usage(wb,GGML_BACKEND_BUFFER_USAGE_WEIGHTS);auto c=ctx();auto*x=tensor(c);auto*ids=ggml_new_tensor_2d(c,GGML_TYPE_I32,1,32);ggml_set_input(x);ggml_set_input(ids);auto*z=tensor(c);z->op=GGML_OP_MUL_MAT_ID;z->src[0]=w;z->src[1]=x;z->src[2]=ids;ggml_set_output(z);auto*g=ggml_new_graph_custom(c,2048,false);ggml_build_forward_expand(g,z);ggml_backend_sched_set_tensor_backend(s,z,&gpu.b);CHECK(ggml_backend_sched_alloc_graph(s,g));CHECK(gpu.query==1&&gpu.reserve==1&&gpu.bind==1);CHECK(ggml_backend_sched_graph_compute(s,g)==GGML_STATUS_SUCCESS);CHECK(gpu.begin==1);if(accepted)CHECK(gpu.end==1&&gpu.cancel==0);else CHECK(gpu.end==0&&gpu.cancel==1&&gpu.copy_cb==2);ggml_backend_sched_free(s);ggml_backend_buffer_free(wb);ggml_free(c);ggml_free(weights);check_clean(gpu,cpu);}
static void noinputs(bool events){Mock gpu,cpu;initialize(gpu,true);initialize(cpu,false);gpu.events=cpu.events=events;ggml_backend_t bes[]={&gpu.b,&cpu.b};auto s=ggml_backend_sched_new(bes,nullptr,2,2048,true,false);auto a=ctx();auto*x=tensor(a);auto ab=ggml_backend_alloc_ctx_tensors_from_buft(a,&gpu.bt);auto b=ctx();auto*y=tensor(b);auto bb=ggml_backend_alloc_ctx_tensors_from_buft(b,&cpu.bt);float values[16];std::fill(values,values+16,3.f);ggml_backend_tensor_set(x,values,0,sizeof(values));ggml_backend_tensor_set(y,values,0,sizeof(values));auto c=ctx();auto*z=ggml_add(c,x,x);auto*w=ggml_add(c,y,y);ggml_set_output(z);ggml_set_output(w);auto*g=ggml_new_graph_custom(c,2048,false);ggml_build_forward_expand(g,z);ggml_build_forward_expand(g,w);CHECK(ggml_backend_sched_alloc_graph(s,g));CHECK(ggml_backend_sched_get_n_splits(s)==2);CHECK(ggml_backend_sched_graph_compute_async(s,g)==GGML_STATUS_SUCCESS);CHECK(gpu.queue.empty());if(events)CHECK(gpu.event_syncs>0);ggml_backend_sched_synchronize(s);ggml_backend_sched_free(s);ggml_backend_buffer_free(ab);ggml_backend_buffer_free(bb);ggml_free(c);ggml_free(a);ggml_free(b);check_clean(gpu,cpu);}
static void inputgrowth(){Mock gpu,cpu;initialize(gpu,true);initialize(cpu,false);ggml_backend_t bes[]={&gpu.b,&cpu.b};auto s=ggml_backend_sched_new(bes,nullptr,2,4096,true,false);auto c=ctx();auto*g=ggml_new_graph_custom(c,4096,false);std::vector<ggml_tensor*>inputs,outputs;for(int i=0;i<80;i++){auto*x=tensor(c);ggml_set_input(x);inputs.push_back(x);auto*z=ggml_add(c,x,x);ggml_set_output(z);outputs.push_back(z);ggml_backend_sched_set_tensor_backend(s,z,&gpu.b);ggml_build_forward_expand(g,z);}CHECK(ggml_backend_sched_alloc_graph(s,g));CHECK(ggml_backend_sched_get_n_splits(s)==1);float values[16];std::fill(values,values+16,4.f);for(auto*x:inputs)ggml_backend_tensor_set(x,values,0,sizeof(values));CHECK(ggml_backend_sched_graph_compute_async(s,g)==GGML_STATUS_SUCCESS);std::fill(values,values+16,100.f);for(auto*x:inputs)ggml_backend_tensor_set(x,values,0,sizeof(values));ggml_backend_sched_synchronize(s);for(auto*z:outputs){float out[16];ggml_backend_tensor_get(z,out,0,sizeof(out));for(float v:out)CHECK(v==8.f);}ggml_backend_sched_free(s);ggml_free(c);check_clean(gpu,cpu);}

int main(){int cases=0;for(int parallel=0;parallel<2;parallel++)for(int events=0;events<2;events++)for(int async=0;async<2;async++){flow(parallel,events,async,41,false,false,false);cases++;}flow(1,true,true,29,true,false,false);cases++;flow(1,true,true,5,false,1,false);cases++;flow(1,true,true,5,false,2,false);cases++;flow(1,true,true,5,false,false,true);cases++;allocation_failure();cases++;graph_inputs();cases++;noinputs(true);cases++;noinputs(false);cases++;inputgrowth();cases++;expertflow(true);cases++;expertflow(false);cases++;printf("{\"status\":\"PASS_SCHEDULER_MOCK_ASYNC\",\"cases\":%d}\n",cases);}
